examples.solution_text:
Count $8$ squares along the base and $5$ vertically from the base to the opposite vertex. The base is $8\text{ m}$ and the perpendicular height is $5\text{ m}$.

[tikz]
\begin{tikzpicture}[x=0.5cm,y=0.5cm,draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\definecolor{gridInk}{HTML}{CCCCCC}
\draw[very thin,color=gridInk] (0,0)--(0,7) (1,0)--(1,7) (2,0)--(2,7) (3,0)--(3,7) (4,0)--(4,7) (5,0)--(5,7) (6,0)--(6,7) (7,0)--(7,7) (8,0)--(8,7) (9,0)--(9,7) (10,0)--(10,7);
\draw[very thin,color=gridInk] (0,0)--(10,0) (0,1)--(10,1) (0,2)--(10,2) (0,3)--(10,3) (0,4)--(10,4) (0,5)--(10,5) (0,6)--(10,6) (0,7)--(10,7);
\draw (0,0) rectangle (10,7);
\draw[thick] (1,1)--(9,1)--(4,6)--cycle;
\draw[dashed] (4,6)--(4,1);
\draw (4,1.3)--(4.3,1.3)--(4.3,1);
\path (5,1) node[below,fill=white,inner sep=1pt] {$8\text{ m}$};
\path (4,3.5) node[right,fill=white,inner sep=1pt] {$5\text{ m}$};
\end{tikzpicture}
[/tikz]

$\begin{align*}\text{Area}&=8\times5\div2\\&=40\div2\\&=20\text{ m}^{2}\end{align*}$

